# Patterns behind the scenes: each groups schools that work the same way.
# Every factual statement here is also carried, with its source, by a school record on the map.
PATTERNS = [
dict(id="doctrine_export", title="Economics exported by contract",
 schools=["uchicago", "puc_chile", "berkeley", "ui_feb", "harvard", "hiid", "mit", "itam", "yale", "cema", "pucrio", "uniandes", "lse", "jvi", "nes", "hse", "ceu"],
 d=["The free-trade policies that swept the developing world after 1970 did not travel on their own. They travelled inside people, and the trips were paid for. In 1956 the US aid agency paid the University of Chicago to rebuild the economics faculty of Chile's Catholic University and to bring its best students to Chicago. In Indonesia the Ford Foundation sent the young lecturers of the University of Indonesia to Berkeley. When a coup or a crisis arrived, General Pinochet in 1973 and General Suharto in 1966, these graduates were ready with a plan, and they took the finance ministry, the planning office and the central bank.",
    "The same pattern ran on through the 1990s. Mexico's finance ministry passed from one graduate of ITAM with a US doctorate to the next, and they took Mexico into NAFTA. In Argentina, Chicago-trained founders of CEMA ran the economy ministry and central bank during the dollar peg and privatisations. In Russia, Harvard advisers paid by USAID sat beside the privatisation team, until a lawsuit ended with Harvard paying 26.5 million dollars. After communism fell, the IMF and other lenders set up the Joint Vienna Institute to retrain the old planners, and new schools in Moscow taught Western economics in English."],
 means="When a country's economic team is trained in one place, its choices are made before it takes office. Voters can change a government, but if the replacement ministers learned their economics in the same departments, on the same scholarships, the policy stays the same. This is how tariff cuts and privatisation spread to dozens of countries in a few decades with few votes held on them.",
 src=[["Chicago Boys", "https://en.wikipedia.org/wiki/Chicago_Boys"], ["Berkeley Mafia", "https://en.wikipedia.org/wiki/Berkeley_Mafia"], ["Harvard Institute for International Development", "https://en.wikipedia.org/wiki/Harvard_Institute_for_International_Development"]]),
dict(id="embassy_pick", title="Embassies pick tomorrow's leaders",
 schools=["ivlp", "fulbright", "chevening", "marshall", "commonwealth", "yali", "yseali", "daad", "jica", "itec", "turkiye_burs", "schwarzman", "yenching", "rhodes"],
 d=["Most rich governments run a programme that picks promising foreigners early and pays for them to spend time in the home country. The selection is done by embassies. The United States' International Visitor Leadership Program cannot be applied for: US embassy staff nominate the visitors, and its administrator says the programme advances US national security priorities and counts more than 350 alumni who became heads of state or government. Britain's Chevening scholars are picked by British embassies for 'leadership potential'; the programme's 2026 report calls it 'an investment in the UK's long-term influence' and boasts of 'access to senior decision-makers worldwide'.",
    "Germany runs the DAAD through its foreign office, Japan trains officials through its aid agency, India through its foreign ministry, Turkey through its own scholarships. China's newest versions are Schwarzman College at Tsinghua and the Yenching Academy at Peking University, built to bring future leaders from around the world to Beijing. Cecil Rhodes's scholarship, founded in 1902 to bind the English-speaking world together, was the model for all of them."],
 means="These programmes are open about their purpose. The governments that pay for them say plainly that they want friends in power abroad, and they count success in heads of state. A leader who spent formative months in Washington, London or Beijing, at that government's expense, will carry its contacts and its outlook into negotiations with it.",
 src=[["Institute of International Education, IVLP", "https://www.iie.org/ivlp"], ["Chevening Impact Report 2026", "https://www.chevening.org/wp-content/uploads/2026/06/Chevening-Impact-Report.pdf"]]),
dict(id="davos", title="The Davos shortlist",
 schools=["ygl", "shapers", "aspen", "eisenhower", "obama"],
 d=["In 1993 the World Economic Forum named its first 'Global Leaders for Tomorrow'. Its own history lists Angela Merkel, Tony Blair, Gordon Brown, Nicolas Sarkozy and José María Aznar in that class, and all of them went on to lead their countries. In 2004 Klaus Schwab relaunched the scheme as the Forum of Young Global Leaders. The Forum chooses members, mostly under 40; no one can apply. Below them, the Global Shapers network picks people under 30 in hundreds of cities.",
    "In 2017, speaking at Harvard's Kennedy School, Schwab said: 'we penetrate the cabinets', and that more than half of Justin Trudeau's cabinet were Young Global Leaders. Alumni have since led France, Finland, New Zealand, Austria, Belgium and Ireland, and the Forum keeps naming ministers while they are in office, including a sitting Thai prime minister and a Montenegrin prime minister in 2025."],
 means="The Forum is a private foundation paid for by about 1,000 of the world's largest companies. By picking rising politicians early and bringing them together with business leaders every year, it builds a network that is in place before they take power. Membership does not show that anyone took orders. It does show which rising politicians the Forum's member companies chose to meet regularly before voters elected them.",
 src=[["Young Global Leaders", "https://en.wikipedia.org/wiki/Young_Global_Leaders"], ["CTV News, Truth Tracker", "https://ctvnews.ca/canada/article/truth-tracker-analyzing-the-world-economic-forum-great-reset-conspiracy-theory"], ["WEF, A Partner in Shaping History", "https://www3.weforum.org/docs/WEF_A_Partner_in_Shaping_History.pdf"]]),
dict(id="successor", title="The successor generation",
 schools=["faf", "atlantikbruecke", "bap", "gmf", "marshall"],
 d=["In 1983 Ronald Reagan called for building ties with Europe's 'successor generation', at a time when many young Europeans opposed US missiles in Europe. The British-American Project for the Successor Generation was founded two years later. When Tony Blair took office in 1997, several of his ministers and his chief of staff were members, and the Guardian wrote that even its supporters joke that the CIA funds it.",
    "France and Germany have their own versions. The French-American Foundation's Young Leaders, picked a few at a time since 1981, include Bill and Hillary Clinton, François Hollande, Emmanuel Macron and Édouard Philippe. Germany's Atlantik-Brücke was founded in 1952 to tie West Germany's elite to the United States, and Friedrich Merz chaired it before becoming chancellor. The German Marshall Fund and Britain's Marshall Scholarship work the same transatlantic seam."],
 means="These clubs pick people before they are famous and give them friends on the other side of the Atlantic. The result is a governing class in Europe whose closest foreign contacts are American, formed by invitation in private meetings, not by any public process.",
 src=[["British-American Project", "https://en.wikipedia.org/wiki/British-American_Project"], ["French-American Foundation", "https://en.wikipedia.org/wiki/French-American_Foundation"], ["Atlantik-Brücke", "https://en.wikipedia.org/wiki/Atlantik-Br%C3%BCcke"]]),
dict(id="officers", title="Officer schools and the coups that follow",
 schools=["whinsec", "cgsc", "usawc", "ndu", "iadc", "sandhurst", "rcds", "saintcyr", "frunze", "nanjing", "fuhsingkang", "ilea", "fbina"],
 d=["Armies send their promising officers abroad for a year, and the host gets a lifelong contact inside a foreign army. The US Army's School of the Americas trained more than 60,000 Latin American officers. In 1996 the Pentagon admitted that its intelligence courses had used manuals advocating executions, torture and blackmail. Its graduates include Manuel Noriega and Roberto D'Aubuisson. Taiwan's Fu Hsing Kang College taught political warfare to Latin American officers, D'Aubuisson again among them.",
    "The pattern did not end with the Cold War. Egypt's Abdel Fattah el-Sisi studied at the US Army War College in 2006 and seized power in 2013. In West Africa, officers who had taken part in US training have led coups in Mali, Burkina Faso and Guinea. A 2017 study in the Journal of Peace Research, covering 189 countries from 1970 to 2009, found that more officers trained in the US programmes IMET and CTFP went with a higher chance of a military coup. Britain's Sandhurst trained the rulers of Jordan, Oman, Brunei and Qatar; the Soviet Frunze Academy trained officers from Moscow's allies."],
 means="Military training abroad can build loyalty between armies that is stronger than an army's loyalty to its own government. When officers trust their foreign trainers more than their own elected government, the trainers' country gains a channel into the one institution that can remove a government by force.",
 src=[["Western Hemisphere Institute for Security Cooperation", "https://en.wikipedia.org/wiki/Western_Hemisphere_Institute_for_Security_Cooperation"], ["Savage and Caverley, 'When human capital threatens the Capitol', Journal of Peace Research 2017", "https://econpapers.repec.org/RePEc:sae:joupea:v:54:y:2017:i:4:p:542-557"], ["The Intercept, 2023, on coups by US-trained officers", "https://theintercept.com/2023/04/10/africom-coup-flintlock/"]]),
dict(id="party_export", title="Party schools for export",
 schools=["cps", "celap", "mjnls", "lenin", "kutv", "sunyatsen", "rudn", "hps_cpsu", "winneba", "nicolopez", "kimilsung_hps", "hcma", "mgimo"],
 d=["Communist states built schools to train other countries' revolutionaries. In the 1920s and 1930s the Comintern ran Moscow schools where foreign communists studied under false names: Ho Chi Minh, Erich Honecker and, by his biographers' account, Jomo Kenyatta among them. Deng Xiaoping and Chiang Ching-kuo, later leaders of the two rival Chinas, were students at the same Moscow university in the 1920s. From 1960 the Soviet Union gave free degrees to students from Africa, Asia and Latin America at the university it named after Patrice Lumumba.",
    "China has revived the model. Its Central Party School, once run by Hu Jintao and then by Xi Jinping, trains its own officials and hosts foreign ones, as does the leadership academy in Shanghai's financial district. In 2022 the Chinese party paid 40 million dollars to open the Mwalimu Julius Nyerere Leadership School in Tanzania for six southern African parties that have ruled since independence, and Xi Jinping sent a letter to its first class."],
 means="A party school teaches how to hold power: how to run a party inside the state, manage the press and keep control through elections. When one ruling party trains another's cadres, it exports a model of government without needing a single soldier or a treaty.",
 src=[["Africa Center for Strategic Studies", "https://africacenter.org/spotlight/china-first-political-school-africa/"], ["Moscow Sun Yat-sen University", "https://en.wikipedia.org/wiki/Moscow_Sun_Yat-sen_University"], ["International Lenin School", "https://en.wikipedia.org/wiki/International_Lenin_School"]]),
dict(id="one_door", title="One door into the state",
 schools=["ena", "scpo", "polytechnique", "oxford", "cambridge", "eton", "todai", "snu", "tsinghua", "lbsnaa", "psc_sg", "royal_college_ma", "ranepa", "cyl", "komsomol", "llg", "harrow", "winchester"],
 d=["In many countries the state has one main door, and it is a school. France's senior civil servants came out of one institution, ENA, which produced four presidents before Macron closed it in 2021. Eton has educated 20 British prime ministers and Oxford most of the rest. In Japan, graduates of one law faculty in Tokyo run the finance ministry. In China, Hu Jintao and Xi Jinping both studied at Tsinghua, and Hu also led the Communist Youth League, whose former officials became a faction of their own. India's administrators all pass through one academy in Mussoorie.",
    "The most literal version is in Rabat. Inside the royal palace, the Collège royal educates the crown prince alongside classmates chosen by the king. Mohammed VI's classmates grew up to become his chief adviser and the head of Morocco's foreign intelligence service."],
 means="When rulers come from one or two schools, they share friends, habits and assumptions long before they hold office. Outsiders find it hard to break in, and the people running the state answer, in practice, to a small circle of former classmates.",
 src=[["École nationale d'administration", "https://en.wikipedia.org/wiki/%C3%89cole_nationale_d%27administration"], ["Royal College (Rabat)", "https://en.wikipedia.org/wiki/Royal_College_(Rabat)"], ["Tsinghua clique", "https://en.wikipedia.org/wiki/Tsinghua_clique"]]),
dict(id="think_franchise", title="The think-tank franchise",
 schools=["mps", "iea", "atlas", "ufm", "heritage", "leadership_inst", "fedsoc", "kas", "fes", "ndi", "iri"],
 d=["In 1947 Friedrich Hayek gathered free-market economists at a hotel above Lake Geneva. One of his admirers, the British chicken farmer Antony Fisher, took Hayek's advice to change minds through ideas rather than elections. He founded the Institute of Economic Affairs in London in 1955 and the Atlas Network in 1981, which now funds and trains about 500 think tanks in around 100 countries. Their alumni enter governments: the IEA said 14 of Boris Johnson's 2019 cabinet were its alumni, and Atlas partners claim a hand in Javier Milei's programme.",
    "In Washington the model is industrial. The Leadership Institute says it has trained more than 160,000 conservatives to win office and staff it. The Heritage Foundation built a recruitment database and a training academy to staff a whole administration. The Federalist Society organised conservative law students in 1982; its long-time leader helped draw up the list from which Supreme Court justices were chosen. German parties do the same abroad with public money, and since 1983 both US parties have trained foreign parties through institutes funded by the National Endowment for Democracy."],
 means="Think tanks do not stand for election, but they train the people who do and write the programmes they carry into office. The money behind them, from foundations, companies and wealthy donors, is largely private and often undisclosed, so voters cannot see who paid to prepare the government they elected.",
 src=[["Atlas Network", "https://en.wikipedia.org/wiki/Atlas_Network"], ["The Guardian, 2019", "https://www.theguardian.com/politics/2019/nov/29/rightwing-thinktank-conservative-boris-johnson-brexit-atlas-network"], ["Leadership Institute", "https://en.wikipedia.org/wiki/Leadership_Institute"]]),
dict(id="faith", title="Faith academies",
 schools=["madinah", "azhar", "qom", "mustafa", "haqqania", "deoband", "imamhatip", "gulen", "navarra", "iese", "panamericana", "anahuac", "strathmore", "pea", "regent", "fellowship", "rss", "skullbones"],
 d=["Religious movements train young people who then take the state. Iran has been ruled since 1979 by clerics trained in the Qom seminary, and its Al-Mustafa International University, with branches in about 50 countries, was sanctioned by the US Treasury in 2020 as a recruiting network for the Quds Force. Saudi Arabia gives free places at its Islamic University of Madinah to foreign students who carry its teaching home. Many Taliban leaders studied at Deobandi seminaries such as Darul Uloom Haqqania, and its graduates took posts in both Taliban governments.",
    "Turkey's president graduated from an Imam Hatip school; his former ally Fethullah Gülen ran schools in more than 100 countries, and the Turkish state says their graduates infiltrated its police, courts and army before the 2016 coup attempt. Opus Dei's universities produced Franco's technocrat ministers and educate Latin America's elites. In the United States, Pat Robertson's Regent University placed more than 150 graduates in the Bush administration, the Fellowship brings legislators and foreign leaders into private prayer cells, and in India the RSS has trained Narendra Modi and much of his party from boyhood. Skull and Bones, Yale's secret society, is the secular version: fifteen students tapped each year, three presidents among them."],
 means="A faith academy forms loyalty to a movement before loyalty to an office. When its graduates run ministries, courts or police forces, the movement's leaders gain influence that no election gave them, and in Turkey's case the state itself came to see a school network as an enemy inside the gates.",
 src=[["US Treasury, 8 December 2020", "https://home.treasury.gov/news/press-releases/sm1205"], ["Gülen movement", "https://en.wikipedia.org/wiki/G%C3%BClen_movement"], ["Regent University", "https://en.wikipedia.org/wiki/Regent_University"]]),
dict(id="revolving", title="The bank and the lender as finishing school",
 schools=["goldman", "mckinsey", "wb_ypp", "imf_icd", "penn", "stanford", "matsushita"],
 d=["Some of the most effective training grounds are employers. Goldman Sachs recruits analysts straight from university, and its alumni have run the US Treasury three times, the European Central Bank, the Bank of England and the governments of Italy, Britain, Australia and Canada. McKinsey trains thousands of graduates who move into ministries while the firm advises them.",
    "The World Bank and the IMF train officials from the countries that borrow from them. The Bank has hired young economists through its Young Professionals Program since 1963, and many of its staff later go home as finance ministers or presidents, sometimes to negotiate with their old employer. Japan offers a private version: Panasonic's founder built an academy that trains future politicians, and one became prime minister."],
 means="When finance ministers and central bankers have spent their formative years at the bank or lender across the table, the line between regulator and regulated, or between borrower and lender, gets thin. The result is a shared view of what counts as sound policy that rarely has to be argued in public.",
 src=[["Goldman Sachs", "https://en.wikipedia.org/wiki/Goldman_Sachs"], ["World Bank", "https://en.wikipedia.org/wiki/World_Bank"]]),
]

